# ------------------------------------------------------------------ sessions

def issue_session(pod, account_id):
    token = secrets.token_urlsafe(32)
    pod.table("aa_sessions").create({
        "token_hash": token_hash(token),
        "account_id": str(account_id),
        "issued_at": iso(),
        "expires_at": iso(now() + timedelta(days=SESSION_DAYS)),
        "revoked": False,
    })
    return token


def resolve_session(pod, token):
    """Token -> account row. Raises ApiError(401) when the session is not valid."""
    if not token:
        raise ApiError("unauthenticated", "Sign in to continue.", 401)
    row = find_one(pod, "aa_sessions", [("token_hash", "eq", token_hash(token))])
    if not row:
        raise ApiError("invalid_session", "Your session is not valid. Sign in again.", 401)
    if row.get("revoked"):
        raise ApiError("session_revoked", "This session was signed out.", 401)
    expires = parse_dt(row.get("expires_at"))
    if expires and expires < now():
        raise ApiError("session_expired", "Your session expired. Sign in again.", 401)
    account = pod.table("aa_accounts").get(str(row["account_id"]))
    if not account or account.get("account_status") != "active":
        raise ApiError("account_unavailable", "This account is not available.", 403)
    try:
        pod.table("aa_sessions").update(str(row["id"]), {"last_used_at": iso()})
    except Exception:
        pass
    return account


def audit(pod, account_id, action, metadata=None):
    try:
        pod.table("aa_audit_logs").create({
            "account_id": str(account_id) if account_id else None,
            "action": action,
            "metadata": metadata or {},
        })
    except Exception:
        pass


def ok(data=None):
    return {"ok": True, "data": data or {}, "error": None}


def fail(error):
    if isinstance(error, ApiError):
        return {"ok": False, "data": None, "error": error.as_dict()}
    return {"ok": False, "data": None,
            "error": {"code": "internal_error", "message": str(error), "status": 500}}


def profile_bundle(pod, account, dir_data=None):
    """Everything the signed-in member needs to render their own profile pages."""
    from_ = dir_data or directory(pod)
    account_id = str(account["id"])
    profile = from_["profiles"].get(account_id) or {}
    prefs = from_["prefs_by_account"].get(account_id) or {}
    return {
        "account": {
            "account_id": account_id,
            "email": account.get("email"),
            "is_demo": bool(account.get("is_demo")),
            "account_status": account.get("account_status"),
        },
        "profile": {
            "display_name": profile.get("display_name") or "",
            "birth_date": str(profile.get("birth_date"))[:10] if profile.get("birth_date") else None,
            "age": age_from_birth_date(profile.get("birth_date")),
            "bio": profile.get("bio") or "",
            "city": profile.get("city") or "",
            "avatar_url": profile.get("avatar_url"),
            "discoverable": bool(profile.get("discoverable", True)),
            "show_age": bool(profile.get("show_age", True)),
            "show_city": bool(profile.get("show_city", True)),
            "onboarding_step": int(profile.get("onboarding_step") or 1),
            "onboarding_completed": bool(profile.get("onboarding_completed")),
            "connection_type": profile.get("connection_type") or "dating",
        },
        "interests": sorted(from_["interests_by_account"].get(account_id, [])),
        "answers": from_["answers_by_account"].get(account_id, {}),
        "preferences": {
            "connection_type": prefs.get("connection_type") or "dating",
            "min_age": int(prefs.get("min_age") or 18),
            "max_age": int(prefs.get("max_age") or 99),
            "weights": weights_of(prefs),
            "include_demo": bool(prefs.get("include_demo", True)),
        },
        "completion": completion_score(profile, from_["interests_by_account"].get(account_id, []),
                                       from_["answers_by_account"].get(account_id, {})),
    }


def completion_score(profile, interests, answers):
    """Weighted completion over the fields the engine actually reads."""
    checks = [
        ("display_name", 10, bool(profile.get("display_name"))),
        ("birth_date", 10, bool(profile.get("birth_date"))),
        ("bio", 20, len(str(profile.get("bio") or "")) >= 40),
        ("city", 5, bool(profile.get("city"))),
        ("interests", 30, len(interests or []) >= 3),
        ("questionnaire", 20, len(answers or {}) >= 3),
        ("visibility", 5, "onboarding_completed" in profile and profile.get("onboarding_completed") is not None),
    ]
    total = sum(weight for _, weight, _ in checks)
    earned = sum(weight for _, weight, done in checks if done)
    return {
        "percent": int(round(earned / total * 100)) if total else 0,
        "checks": [{"key": key, "weight": weight, "done": done} for key, weight, done in checks],
    }

